/* ===== 纯函数区（第一个无属性 script）：可被 Node _test.js 提取并断言 ===== */
// Code 128 图案表（符号 0..106，6 元素宽度，停符 7 元素）
var C128 = ['212222','222122','222221','121223','121322','131222','122213','122312','132212','221213',
'221312','231212','112232','122132','122231','113222','123122','123221','223211','221132',
'221231','213212','223112','312131','311222','321122','321221','312212','322112','322211',
'212123','212321','232121','111323','131123','131321','112313','132113','132311','211313',
'231113','231311','112133','112331','132131','113123','113321','133121','313121','211331',
'231131','213113','213311','213131','311123','311321','331121','312113','312311','332111',
'314111','221411','431111','111224','111422','121124','121421','141122','141221','112214',
'112412','122114','122411','142112','142211','241211','221114','413111','241112','134111',
'111242','121142','121241','114212','124112','124211','411212','421112','421211','212141',
'214121','214211','412121','111143','111341','131141','114113','114311','411113','411311',
'113141','114131','311141','411131','211412','211214','2331112'];

function expandPattern(p){
  var mods='', i;
  for(i=0;i<p.length;i++){
    var ch = (i % 2 === 0) ? '1' : '0';
    mods += ch.repeat(parseInt(p[i],10));
  }
  return mods;
}
function code128B(text){
  var vals=[105], i;
  for(i=0;i<text.length;i++){
    var c=text.charCodeAt(i);
    var v = (c>=32 && c<=126) ? (c-32) : 31; // 31 = '?'
    vals.push(v);
  }
  var sum=105;
  for(i=0;i<text.length;i++) sum += (i+1)*vals[i+1];
  vals.push(sum % 103);
  vals.push(106);
  var mods='';
  for(i=0;i<vals.length;i++) mods += expandPattern(C128[vals[i]]);
  return { modules: mods, text: text };
}
// EAN-13: 返回 13 位（含校验位），校验位缺失时计算
function ean13Checksum(d12){
  var s=0;
  for(var i=0;i<12;i++){
    var d=parseInt(d12[i],10);
    s += (i % 2 === 0) ? d : d*3; // i 从 0 起：奇位×1，偶位×3
  }
  return (10 - (s % 10)) % 10;
}
var EAN_L = ['0001101','0011001','0010011','0111101','0100011','0110001','0101111','0111011','0110111','0001011'];
var EAN_G = ['0100111','0110011','0011011','0100001','0011101','0111001','0000101','0010001','0001001','0010111'];
var EAN_R = ['1110010','1100110','1101100','1000010','1011100','1001110','1010000','1000100','1001000','1110100'];
var EAN_PARITY = ['AAAAAA','AABABB','AABBAB','AABBBA','ABAABB','ABBAAB','ABBBAA','ABABAB','ABABBA','ABBABA'];
function ean13(input){
  var d = String(input).replace(/\D/g,'');
  if(d.length === 12) d = d + ean13Checksum(d);
  if(d.length !== 13) return null;
  var first = parseInt(d[0],10);
  var mods = '101'; // 起始保护
  for(var i=1;i<=6;i++){
    var v = parseInt(d[i],10);
    mods += (EAN_PARITY[first][i-1] === 'A') ? EAN_L[v] : EAN_G[v];
  }
  mods += '01010'; // 中间保护
  for(var j=7;j<=12;j++){
    mods += EAN_R[parseInt(d[j],10)];
  }
  mods += '101'; // 结束保护
  return { modules: mods, text: d };
}
function upca(input){
  var d = String(input).replace(/\D/g,'');
  if(d.length === 11) d = d + ean13Checksum('0'+d);
  if(d.length === 12) d = '0' + d; // 转为 EAN-13（首位 0）
  if(d.length !== 13) return null;
  var r = ean13(d);
  if(!r) return null;
  // UPC-A 标签：首数字在左、末数字在右（视觉约定）
  return { modules: r.modules, text: r.text.slice(1), upcaLabel: d.slice(1,7)+' '+d.slice(7,12) };
}
function escapeXml(s){
  return String(s).replace(/[<>&'"]/g, function(c){
    return {'<':'&lt;','>':'&gt;','&':'&amp;',"'":'&apos;','"':'&quot;'}[c];
  });
}
function renderSvg(modules, label, opts){
  opts = opts || {};
  var mw = opts.moduleWidth || 3, height = opts.height || 110, qz = opts.quiet || 10;
  var totalMods = modules.length + qz*2;
  var width = totalMods * mw;
  var bars='', x = qz*mw, i;
  for(i=0;i<modules.length;i++){
    if(modules[i]==='1') bars += '<rect x="'+x+'" y="0" width="'+mw+'" height="'+height+'" fill="#0A0A0B"/>';
    x += mw;
  }
  return '<svg xmlns="http://www.w3.org/2000/svg" width="'+width+'" height="'+(height+28)+'" viewBox="0 0 '+width+' '+(height+28)+'">'
    + '<rect x="0" y="0" width="'+width+'" height="'+(height+28)+'" fill="#FFFFFF"/>'
    + bars
    + '<text x="'+(width/2)+'" y="'+(height+20)+'" text-anchor="middle" font-family="monospace" font-size="16" fill="#0A0A0B">'+escapeXml(label)+'</text>'
    + '</svg>';
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { C128:C128, expandPattern:expandPattern, code128B:code128B, ean13Checksum:ean13Checksum,
    ean13:ean13, upca:upca, renderSvg:renderSvg };
}
if (typeof window !== 'undefined') {
  window.BarcodeForgePure = { C128:C128, expandPattern:expandPattern, code128B:code128B, ean13Checksum:ean13Checksum,
    ean13:ean13, upca:upca, renderSvg:renderSvg };
}
